npm install @microsoft/applicationinsights

import { ApplicationInsights } from "@microsoft/applicationinsights";

const appInsights = new ApplicationInsights({
  config: {
    connectionString: process.env.APPLICATIONINSIGHTS_CONNECTION_STRING,
    enableAutoCollectRequests: true,
    enableAutoCollectDependencies: true,
    enableAutoCollectExceptions: true,
    enableAutoCollectPerformance: true
  }
});

appInsights.loadAppInsights();
appInsights.trackTrace({ message: "App started", severity: 1 });

// Track a custom event
appInsights.trackEvent({
  name: "CheckoutCompleted",
  properties: {
    orderId: "order-789",
    total: 149.99,
    paymentMethod: "credit-card"
  }
});

// Track a numeric metric
appInsights.trackMetric({
  name: "CartValue",
  average: 149.99
});

// Track a custom trace (debugging information)
appInsights.trackTrace({
  message: "Discount code applied: SAVE20",
  severity: 1 // 1=Verbose, 2=Information, 3=Warning, 4=Error
});

try {
  await processPayment(order);
} catch (error) {
  appInsights.trackException({
    exception: error,
    properties: {
      orderId: order.id,
      customerId: order.customerId
    }
  });
}
